      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "A radiolabeled pyrrolidinylmethoxy-pyridine analog reached 3.01 %ID/g in mouse brain at 15 minutes after injection and was concluded to show relatively high brain uptake.",
