    },
    {
      "card_ids": ["C03"],
      "claim": "Nicotine, a close structural relative, showed a brain/blood ratio of 5.6 within 1 minute after i.v. injection in mice, demonstrating rapid and apparently unhindered passage across the blood-brain barrier.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple direct in-vivo studies across mice, rats, and humans consistently demonstrate meaningful CNS access for structurally related nicotinic ligands, including oral, i.v., and PET evidence. The single negative record is from a lower-similarity compound and is outweighed by the extensive positive direct evidence.",
  "evidence_gaps": [
    "No direct query-specific in-vivo data are available; all evidence comes from analogs.",
    "One low-similarity negative record (C08) for 3-AP is present, but its structural similarity to the query is limited.",
    "Some positive records are qualitative or from different species and routes, though the direction is consistent."
  ],
